/** Noto Sans Devanagari embedded as a WOFF2 data URI (2026-07-20).
 *  loadFont works locally (macOS has a Devanagari system font) but the 4K GCE
 *  headless Chrome has NO Indic system font, so Hindi rendered as tofu boxes.
 *  Matches the PROVEN sketchFonts.ts pattern exactly: WOFF2 (not TTF) data URI,
 *  font-display:block, injected at the DocWide root so every scene type gets it.
 *  OFL-licensed (Noto). */
export const DEVANAGARI_FONT_CSS = `@font-face { font-family: 'Noto Sans Devanagari'; font-weight: 400; font-style: normal; font-display: block; src: url(data:font/woff2;base64,) format('woff2'); }`;
